public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    return new IsomorphicGraphMapping<V, E>() {
        @Override
        public boolean isAutomorphism(Graph<V, E> potential) {
            if (potential == null || potential.vertexCount() != graph.vertexCount()) {
                return false;
            }
            for (V vertex : graph.vertexSet()) {
                if (!potential.containsVertex(vertex)) {
                    return false;
                }
                if (!potential.getVertex(vertex).equals(vertex)) {
                    return false;
                }
            }
            return true;
        }

        @Override
        public IsomorphicGraphMapping<V, E> compose(IsomorphicGraphMapping<V, E> mapping) {
            return new IsomorphicGraphMapping<V, E>() {
                @Override
                public boolean isAutomorphism(Graph<V, E> potential) {
                    if (!potential.vertexCount() == graph.vertexCount()) {
                        return false;
                    }
                    for (V vertex : graph.vertexSet()) {
                        if (!potential.containsVertex(vertex)) {
                            return false;
                        }
                        if (!potential.getVertex(vertex).equals(mapping.isomorphism().getVertex(vertex))) {
                            return false;
                        }
                    }
                    return true;
                }

                @Override
                public IsomorphicGraphMapping<V, E> compose(IsomorphicGraphMapping<V, E> other) {
                    return this;
                }
            };
        }

        @Override
        public Map<V, V> isomorphism() {
            return new HashMap<>(graph.vertexSet().stream().collect(Collectors.toMap(Function.identity(), Function.identity())));
        }
    };
}

