    if (target instanceof CompleteBipartiteGraph) {
        return;
    }

    // Calculate the number of vertices in each partition
    int part1Size = resultMap.size();
    int part2Size = target.getVertices().size() - part1Size;

    // Create two sets of nodes for each partition
    String[] part1Nodes = new String[part1Size];
    int[] part2Vertices = new int[part2Size];

    // Assign nodes from resultMap to the first partition
    int index = 0;
    for (V node : resultMap.values()) {
        part1Nodes[index] = (String) node;
        index++;
    }

    // Assign nodes from the source graph to the second partition
    int part2Index = 0;
    for (V node : target.getVertices()) {
        boolean found = false;
        for (V resultNode : resultMap.values()) {
            if (node.equals(resultNode)) {
                found = true;
                break;
            }
        }
        if (!found) {
            part2Vertices[part2Index] = (int) node;
            part2Index++;
        }
    }

    // Create source and target graphs
    Graph<V,E> sourceGraph = new Graph<V,E>();
    Graph<V,E> targetGraph = new Graph<V,E>();

    // Add nodes to source graph
    for (String node : part1Nodes) {
        sourceGraph.addNode(node);
    }

    // Add nodes to target graph
    for (int vertex : part2Vertices) {
        targetGraph.addNode((String) vertex);
    }

    // Create edges between the two partitions
    for (String v1 : part1Nodes) {
        for (String v2 : part2Nodes) {
            sourceGraph.addEdge(v1, v2);
            targetGraph.addEdge((String) v2, v1);
        }
    }

    // Set the source and target graphs on the resultList
    resultMap.put("source", sourceGraph);
    resultMap.put("target", targetGraph);
}

