public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int messageSize = schema.getMessageSize(message);
    int totalSizeWithLength = messageSize + 4;
    byte[] messageBuffer = schema.messageToBuffer(message);
    byte[] lengthBuffer = ByteBuffer.allocate(4).putInt(totalSizeWithLength).array();

    out.write(lengthBuffer);
    out.write(messageBuffer);
    return totalSizeWithLength + messageSize;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // first write the byte length of the message
    byte length = (byte) schema.length(message);
    out.write(length);

    // then write the actual message
    try (var stream = new ByteBufferInputStream(schema.data(message))) {
        int read = stream.read(buffer.buffer);
        for (int i = 0; i < read; i++) {
            out.write(buffer.buffer[i]);
        }
    }

    return schema.length(message);
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int messageLength = schema.computeMessageSize(message);
    byte[] messageBytes = schema.encode(message);

    byte[] lengthMessage = ByteBuffer.allocate(4).putInt(messageLength).array();
    out.write(lengthMessage);
    out.write(messageBytes);

    return messageLength + messageBytes.length;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int length = schema.encode(message, out, buffer);
    out.write(length & 0xFF);
    out.write((length >> 8) & 0xFF);
    out.write((length >> 16) & 0xFF);
    out.write((length >> 24) & 0xFF);
    return length + 4;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the object message using the schema
    int serializedLength = schema.encoder().encode(out, message);

    // Write the length of the serialized message to the output stream
    int lengthWritten = out.write(serializedLength);

    // Write the serialized message to the output stream
    out.write(buffer.data, 0, buffer.used);

    return lengthWritten + serializedLength;
}

