protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    long duration = end - start;
    long minTime = -FETCH_DATA_DURATION / 2;
    long maxTime = FETCH_DATA_DURATION / 2;

    if (minTime < duration) {
        start -= minTime;
    } else {
        start = 0;
    }

    if (maxTime < duration) {
        end += maxTime;
    } else {
        end = end - duration;
    }

    ranges.add(new TimeRange(start, end));
    return ranges;
}

