public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Check edge case: if dayStep is 0 or timeBucket is 0, return 0
    if (dayStep == 0 || timeBucket == 0) {
        return 0;
    }

    // Calculate the new time bucket after applying the compression
    return Math.floor((timeBucket / dayStep) * dayStep);
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    long baseYear = timeBucket / (1000 * 365 * 86400);
    long baseMonth = (timeBucket / (1000 * 365 * 86400)) % 12;
    long baseDay = (timeBucket % (1000 * 365 * 86400)) % 86400;
    long baseWeek = (baseDay - baseDay % (86400 / dayStep)) / (86400 / dayStep);

    // Process base year and base month
    if (startTimeStep != 0 && baseMonth >= startTimeStep) {
        baseMonth -= startTimeStep - 1;
    }

    // Process base day
    if (startTimeStep != 0 && baseDay >= startTimeStep) {
        baseDay -= startTimeStep - 1;
    }

    // Calculate the compressed time bucket
    long compressedTimeBucket = (baseYear * (1000 * 365 * 86400)) + (baseMonth * (1000 * 86400)) + baseDay;

    return compressedTimeBucket;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / (24 * 60 * 60 * 1000);
    long month = (timeBucket / (24 * 60 * 60 * 1000)) % 12;
    long day = (timeBucket / (24 * 60 * 60 * 1000)) % 31;
    long reducedYear = year %.dayStep;
    long reducedMonth = month % dayStep;
    long reducedDay = day % dayStep;
    long truncatedYear = year - reducedYear;
    long truncatedMonth = month - reducedMonth;
    long truncatedDay = day - reducedDay;
    return truncatedYear * (24 * 60 * 60 * 1000) + truncatedMonth * (24 * 60 * 60 * 1000) + truncatedDay * (24 * 60 * 60 * 1000);
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket < 0) {
