    }
    // Find the first day that is a multiple of the dayStep
    BigDecimal bd = new BigDecimal(timeBucket);
    bd = bd.setScale(0, BigDecimal.ROUND_HALF_UP);
    long firstDay = bd.longValue();
    // Determine the compressed time bucket
    long compressedTimeBucket = firstDay - (firstDay % dayStep);
    return compressedTimeBucket;
}

