public static int computeUTF8Size(final CharSequence str,final int index,final int length) {
    if (str == null || index < 0 || index > str.length() || length <= 0 || index + length > str.length()) {
        throw new IllegalArgumentException("Invalid input");
    }

    try {
        for (int i = index; i < index + length; i++) {
            final char c = str.charAt(i);
            if (c >= 0x80) {
                if (c >= 0xC0 && c <= 0xDF) {
                    i++;
                    if (i >= index + length) {
                        return length;
                    }
                } else if (c >= 0xE0 && c <= 0xEF) {
                    i += 2;
                    if (i >= index + length) {
                        return length;
                    }
                } else if (c >= 0xF0 && c <= 0xF7) {
                    i += 3;
                    if (i >= index + length) {
                        return length;
                    }
                } else {
                    throw new IllegalArgumentException("Unexpected UTF-8 encoding");
                }
            }
        }
        return length;
    } catch (Exception e) {
        throw new RuntimeException("Error computing UTF-8 size", e);
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
