        if((str.charAt(i) & 0xFC00) != 0xD800) {
            byteLength++;
        } else if(str.charAt(i) == 0xE000) {
            byteLength += 2;
        } else {
            byteLength += 3;
        }
    }

    return byteLength;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len) throws IndexOutOfBoundsException {
    if (index < 0 || index > str.length()) {
        throw new IndexOutOfBoundsException("Index is out of bounds");
    }
    if (len < 0) {
        throw new IllegalArgumentException("Length cannot be negative");
    }

    int pos = index;
    if (len > 0) {
        if (str.charAt(pos) <= 0x007f) {
            --len;
            pos++;
        } else if (str.charAt(pos) <= 0x07ff) {
            len -= 2;
            pos += 2;
        } else if (str.charAt(pos) <= 0xffff) {
            len -= 3;
            pos += 3;
        } else {
            len -= 4;
            pos += 4;
        }
    }
    return pos - index;
}

