public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
    if (str == null || index < 0 || len < 0) {
        throw new IllegalArgumentException("Invalid input: str is null, index is negative, or len is negative");
    }
    --index;
    while (index >= 0 && len > 0) {
        int contBits = str.charAt(index--);
        len--;
        if ((contBits & 0x80) == 0x00) {
            // 1 byte
        } else if ((contBits & 0xE0) == 0xC0) {
            // 2 bytes
            int next = str.charAt(index--);
            contBits = (contBits & 0x1F) << 6 | (next & 0x3F);
        } else if ((contBits & 0xF0) == 0xE0) {
            // 3 bytes
            int next = str.charAt(index--);
            int next2 = str.charAt(index--);
            contBits = (contBits & 0x0F) << 12 | (next & 0x3F) << 6 | (next2 & 0x3F);
        } else if ((contBits & 0xF8) == 0xF0) {
            // 4 bytes
            int next = str.charAt(index--);
            int next2 = str.charAt(index--);
            int next3 = str.charAt(index--);
            contBits = (contBits & 0x07) << 18 | (next & 0x3F) << 12 | (next2 & 0x3F) << 6 | (next3 & 0x3F);
        }
    }
    return len;
}

