ByteVector function(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        // We need to handle the case where byteArrayValue is null
        // Put 'byteLength' nullbytes into this byte vector.
        int loc0 = this.length;
        while (loc0 < this.data.length) {
            this.data[loc0++] = (byte) 0;
        }
        this.length = loc0;
