    } else {
        // We need to handle the case where byteArrayValue is not null
        // Copy the specified number of bytes from byteArrayValue into this byte vector.
        int loc0 = this.length;
        if (loc0 + byteLength > this.data.length) {
            // If the target length is greater than the current length, we need to enlarge the vector.
            this.enlarge(byteLength + this.data.length - loc0);
        }
        for (int i = 0; i < byteLength; i++) {
            this.data[loc0++] = byteArrayValue[byteOffset + i];
        }
        this.length = loc0;
        return this;
