public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    ByteBuffer buffer = session.getByteBuffer();
    byte[] utf8Bytes = str.toString().getBytes(StandardCharsets.UTF_8);
    buffer.write(utf8Bytes);
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb) throws WriterNotOpenException, UnsupportedEncodingException {
    if (!session.isOpen())
        throw new WriterNotOpenException();

    for (int i = 0; i < str.length(); ++i) {
        char ch = str.charAt(i);
        if (ch > 0xFF) { // UTF-16 characters represent as多个字节
            // Write 2-bytes for UTF-16 high surrogate
            lb.write((byte)(0xD800 | ((ch -'A') & 0x3F)));// (ch -'A')&0x3F
            // Write the UTF-16 low surrogate
            lb.write((byte)(0xDC00 | ((ch-'A') & 0x3F)));// (ch -'A')&0x3F
        } else {
            // Normal ASCII character, write single byte
            lb.write((byte)ch);
        }
    }
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb) {
    try {
        // Create a new LinkedListBuffer to hold the utf-8 encoded bytes
        LinkedBuffer utf8Buffer = new LinkedBuffer(lb.getBufferSize() + str.length() * 2);
        // Add the utf-8 encoded bytes to the buffer
        ByteBufUtil.writeUTF8(lb, utf8Buffer, 0, str.length(), str.toString().getBytes());
        return utf8Buffer;
    } catch (InsufficientStorageException e) {
        // Handle the case when the buffer is not large enough
        throw new GzipBufferException(e.getMessage());
    }
}

public static LinkedBuffer writeUTF8(CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || str.length() == 0) {
        return lb;
    }
    for (int i = 0, len = str.length(); i < len; i++) {
        if (session.writeByte((byte) ((int) str.charAt(i)))) {
            return lb;
        }
    }
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb){
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    byte[] utf8Bytes = str.toString().getBytes(StandardCharsets.UTF_8);
    writeUTF8(utf8Bytes, 0, utf8Bytes.length, lb, session);
    lb.flip();
    lb.limit(lb.position());
    return lb;
}

