public class URIUtil {

    private static final boolean DEFAULT_ENCODING = StandardCharsets.UTF_8.name();
    private static final Pattern ENCODED_CHARACTERS_PATTERN = Pattern.compile("[\\\\/=;&]+");
    private boolean decode = false;
    private String baseUrl;

    public List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        if (u == null) { return null; }
        this.decode = decode;
        String path = u.getPath();

        if (path.startsWith("/")) {
            path = path.substring(1);
        }

        List<PathSegmentImpl> segments = new ArrayList<>();
        Matcher matcher = ENCODED_CHARACTERS_PATTERN.matcher(path);
        for (int i = 0; i < path.length(); i++) {
            if (matcher.find()) {
                String segment = path.substring(i, matcher.start());
                if (decode) {
                    segment = URLDecoder.decode(segment, DEFAULT_ENCODING);
                }
                segments.add(new PathSegmentImpl(segment));
            } else {
                segments.add(new PathSegmentImpl(path.substring(i)));
            }
        }

        return segments;
    }
}

