public class StringSupplier implements Supplier<String> {
    private Map<String, Integer> sequence;
    private LinkedHashSet<Integer> usedSequence;

    public StringSupplier(int start) {
        this.sequence = new HashMap<>();
        this.usedSequence = new LinkedHashSet<>();
        updateSequence(start);
    }

    private void updateSequence(int start) {
        for (int i = start; i <= 1000000; i++) {
            sequence.put(String.valueOf(i), i);
            usedSequence.add(i);
        }
    }

    @Override
    public String get() {
        if (usedSequence.isEmpty()) {
            throw new RuntimeException("No more available strings.");
        }

        int nextAvailable = usedSequence.iterator().next();
        usedSequence.remove(nextAvailable);
        return sequence.get(String.valueOf(nextAvailable));
    }
}

