private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    for (int i = 2; i * i <= number; i++) {
        if (number % i == 0) {
            return false;
        }
    }
    return true;
}

private static int enlargePrime(int currentPrime, int growthRate) {
    currentPrime = (int) (currentPrime * Math.exp(growthRate));
    if (!isPrime(currentPrime)) {
        throw new IllegalArgumentException("The calculated prime number is not prime.");
    }
    return currentPrime;
}

