    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        if (escaping) {
            switch (c) {
                case '\'':
                    if (i + 1 < str.length() && str.charAt(i + 1) == '\'') {
                        unescaped.append('\''); // Skip the second '\'' for escape
                        escaping = false;
                    } else {
                        unescaped.append('\\'); // Append the escaped '\' for closing quote
                        escape = true;
                    }
                    break;
                case '\n':
                    unescaped.append(CR); // Reconstruct newline character
                    break;
                default:
                    unescaped.append(c); // Append non-escaped character
                    break;
            }
        } else {
            switch (c) {
                case '\'':
                    escaping = true;
                    break;
                case 'n':
                    unescaped.append(LF); // Reconstruct newline character
                    break;
                default:
                    unescaped.append(c);
                    break;
            }
        }
    }

    return unescaped.toString();
}

