public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Create a new graph path
    GraphPath<V, E> path = new GraphPath<>(graph);

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Add the edge direction to the path
        V from = graph.source(edge);
        V to = graph.target(edge);
        path.addEdge(from, to);
        path.addEdge(to, from);
    }

    // Return the created graph path
    return path;
}

public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
	if (tour == null || tour.isEmpty() || graph == null) {
		throw new IllegalArgumentException("Inputs cannot be null or empty");
	}
	if (graph.getEdgeCount() != tour.size()) {
		throw new IllegalArgumentException("Edge set does not match the number of edges in the graph");
	}

	Stack<V> stack = new Stack<>();
	for (E edge : tour) {
		V source = edge.getSource();
		V target = graph.getEdge(edge).getTarget();
		if (!stack.isEmpty() && target.equals(stack.peek())) {
			continue; // Skip if edge is a loop
		}
		while (!stack.isEmpty() && stack.peek() != source) {
			stack.pop();
		}
		stack.push(target);
	}

	GraphPath<V,E> graphPath = new GraphPath<>();
	while (!stack.isEmpty()) {
		graphPath.visit(stack.pop());
	}
	return graphPath;
}

