private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;
    for (int bound : bounds) {
        totalSum += bound;
        suffixSum.add(totalSum);
    }
    return new Pair<>(suffixSum, totalSum);
}

import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;

class Solution {
    public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        List<Long> suffixSums = bounds.stream().collect(Collectors.collectingAndThen(Collectors.toList(),_vals -> {
            int n = vals.size();
            long totalSum = vals.stream().mapToLong(Long::longValue).sum();
            long sumSoFar = 0;
            List<Long> suffixSumList = new ArrayList<>();
            for (int i = n - 1; i >= 0; i--) {
                sumSoFar += vals.get(i);
                suffixSumList.add(totalSum - sumSoFar);
            }
            Collections.reverse(suffixSumList);
            return suffixSumList;
        }));
        return new Pair<>(suffixSums, Long.valueOf(suffixSums.stream().mapToLong(Long::longValue).sum()));
    }
}

public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize the computed suffix sum list and the sum of all elements
    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0;

    // Traverse the list from right to left
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Update the current element with its new value and add it to the suffix sum list
        bounds.set(i, sum);
        // Update the sum by adding the current element
        sum += bounds.get(i);
    }

    // Return the computed pair of suffix sum list and a sum of all elements
    return Pair.of(suffixSum, sum);
}

/** 
 * Computes a suffix sum of the  {@code bounds}. Returns computed suffix sum and the sum of all elements in the  {@code bounds list}.
 * @param bounds list of integers.
 * @return computed pair of suffix sum list and a sum of all elements.
 */
private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    int length = bounds.size();
    List<Integer> suffixSumList = new ArrayList<>();
    long sumOfAllElements = 0;

    for (int i = length - 1; i >= 0; i--) {
        sumOfAllElements += bounds.get(i);
        suffixSumList.add(sumOfAllElements);
    }

    return Pair.of(suffixSumList, sumOfAllElements);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    Long sumAllElements = 0;
    List<Integer> suffixSum = new ArrayList<>();

    for (int i = bounds.size() - 1; i >= 0; i--) {
        suffixSum.add(bounds.get(i));
        sumAllElements += bounds.get(i);
    }

    return new Pair<>(suffixSum, sumAllElements);
}

