            break;
        }

        // Convert Base64 character to integer
        if ('A' <= c && c <= 'Z') {
            c -= 'A';
        } else if ('a' <= c && c <= 'z') {
            c -= 'a';
        } else if ('0' <= c && c <= '9') {
            c -= '0';
        } else if (c == '+') {
            c = 62;
        } else if (c == '/') {
            c = 63;
        } else {
            throw new IllegalArgumentException("Invalid Base64 character");
        }

        // Decode the 6-bit group and append to decoded string
        int group = (c & 32) << 8;
        group |= (c & 63);
        decoded.append((char) (group >>> 16));
        decoded.append((char) (group >>> 8));
        decoded.append((char) (group & 0xFF));
    }

    return decoded.toString();
}

public static String base64Decode(final String s){
    int len = s.length();
    if ((len & 0x01) != 0) {
        throw new IllegalArgumentException("Invalid base64 length");
    }
    byte[] decodedBytes = new byte[len / 2];
    for ( int i = 0; i < len; i += 2 ) {
        decodedBytes[i / 2] = (byte) ((base64DigitToByte(s.charAt(i)) << 4) | base64DigitToByte(s.charAt(i + 1)));
    }
    return new String(decodedBytes, StandardCharsets.UTF_8);
}

