 * Computes the global separator list of the  {@code graph}. More precisely, for every edge $e$ in the $G = (V, E)$ computes list of minimal separators $S_e$ in the neighborhood of $e$ and then concatenates these lists. Note: the result may contain duplicates
 * @return the list of minimal separators of every edge $e$ in the inspected graph
 */
private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>,E>> separatorList = new ArrayList<>();
    for (E edge : graph.getEdges()) {
        List<List<Pair<Integer,Integer>>> neighborhoodSeparators = new ArrayList<>();
        List<Integer> connectedVertices = graph.getConnectedVertices(edge);

        for (Integer vertex : connectedVertices) {
            List<Pair<Integer,Integer>> neighborhoodSeparatorsForVertex = new ArrayList<>();
            for (DirectedEdge neighborEdge : graph.getNeighbors(vertex)) {
                if (neighborEdge != edge) {
                    List<Integer> prefix = new ArrayList<>();
                    prefix.addAll(connectedVertices);
                    prefix.remove(vertex);
                    prefix.remove(neighborEdge.getToVertex());
                    List<Integer> suffix = new ArrayList<>();
                    suffix.addAll(connectedVertices);
                    suffix.remove(vertex);
                    suffix.remove(neighborEdge.getFromVertex());

                    List<List<Integer>> prefixesSufixes = generatePrefixSuffixes(prefix, suffix);
                    for (List<Integer> prefixList : prefixesSufixes) {
                        neighborhoodSeparatorsForVertex.add(new Pair<>(prefixList, edge));
                    }
                }
            }
            neighborhoodSeparators.add(neighborhoodSeparatorsForVertex);
        }

        separatorList.add(new Pair<>(neighborhoodSeparators, edge));
    }

    return separatorList;
}

private List<List<Integer>> generatePrefixSuffixes(List<Integer> prefix, List<Integer> suffix) {
    List<List<Integer>> result = new ArrayList<>();
    result.add(new ArrayList<>(prefix));
    result.add(new ArrayList<>(suffix));

    for (int i = 1; i < prefix.size(); i++) {
        List<Integer> prefixSubset = prefix.subList(0, i);
        List<Integer> suffixSubset = suffix.subList(i, suffix.size());
        List<List<Integer>> betweenPrefixSuffix = generatePrefixSuffixes(prefixSubset, suffixSubset);

        for (List<Integer> betweenPrefixSuffixList : betweenPrefixSuffix) {
            result.add(prefixSubset);
            result.add(betweenPrefixSuffixList);
            result.add(suffixSubset);
        }
    }

    return result;
}

