    }

    Rectangle viewBounds = pane.getViewport().getViewRect();
    Rectangle tableBounds = table.getBounds();
    int tableRowIndex = (row + 1) * table.getRowHeight();

    int scrollAdjustment = ((tableRowIndex - (viewBounds.y + viewBounds.height))) / table.getRowHeight();

    if (scrollAdjustment != pane.getVerticalScrollBar().getValue()) {
        pane.getVerticalScrollBar().setValue(scrollAdjustment);
        // Wait enough time for the table to repaint the newly selected row
