public static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices){
    // Check if the input graph is null or vertices is null
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices cannot be null");
    }

    int numVertices = vertices.size();

    // If there are fewer than 2 vertices, the graph is always complete
    if (numVertices <= 1) {
        return true;
    }

    // Check if each vertex is connected to every other vertex in the set of vertices
    for (V vert : vertices) {
        Set<V> remainingVertices = new HashSet<>(vertices);
        remainingVertices.remove(vert);

        for (V remaining vert : remainingVertices) {
            if (!graph.containsEdge(vert, remainingVert)) {
                return false;
            }
        }
    }

    return true;
}

