public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    FileInputStream fis = new FileInputStream(file);
    ObjectInputStream ois = new ObjectInputStream(fis);
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        int start = (int) range.getStartTime();
        int end = (int) range.getEndTime();
        List<ThreadSnapshot> rangeSnapshots = (List<ThreadSnapshot>) ois.readObject();
        for (ThreadSnapshot snapshot : rangeSnapshots) {
            if (snapshot.getStartTime() >= start && snapshot.getEndTime() <= end) {
                threadSnapshots.add(snapshot);
            }
        }
    }
    ois.close();
    fis.close();
    return threadSnapshots;
}

